/* Fixed software authorship, separate from editable astrologer contact details. */
(()=>{'use strict';const NAME='Nitin Rajendra Talegaonkar',MOBILE='+918412098690',CREDIT='Software Developer Name: '+NAME+' · Mob: '+MOBILE;
function apply(root=document){const value=id=>document.getElementById(id)?.value.trim()||'',astro=[value('astroName')?'Astrologer: '+value('astroName'):'',value('astroAddress')?'Address: '+value('astroAddress'):'',value('astroMobile')?'Contact: '+value('astroMobile'):''].filter(Boolean).join(' · ');for(const footer of root.querySelectorAll('.report-developer-footer')){footer.dataset.fixedDeveloper='true';footer.replaceChildren();const matchmaking=footer.closest('[data-report-section="matchmaking"]'),name=value('astroName'),defaultName=name==='Astro.Nitin Talegaonkar'||name===NAME,matchAstro=name&&!defaultName?'Astrologer: '+name:'';if(matchmaking){if(matchAstro){const a=(root.ownerDocument||root).createElement('div');a.className='report-astrologer-credit';a.textContent=matchAstro;footer.append(a);}const d=(root.ownerDocument||root).createElement('div');d.className='report-fixed-developer-credit';d.dataset.noLocalize='true';d.textContent=(defaultName?'Astrologer & Software Developer: ':'Software Developer: ')+NAME;footer.append(d);continue;}if(astro){const line=root.ownerDocument?.createElement('div')||root.createElement('div');line.className='report-astrologer-credit';line.textContent=astro;footer.append(line);}const line=root.ownerDocument?.createElement('div')||root.createElement('div');line.className='report-fixed-developer-credit';line.dataset.noLocalize='true';line.textContent=CREDIT;footer.append(line);}const footer=root.querySelector('#softwareDeveloperFooter');if(footer){footer.textContent='Native: '+(value('name')||'Untitled Kundali');footer.dataset.noLocalize='true';}}
const oldRender=window.renderReport;if(oldRender)window.renderReport=function(...args){const result=oldRender.apply(this,args);apply();return result;};const oldApply=window.applyAstrologerSettings;if(oldApply)window.applyAstrologerSettings=function(...args){const result=oldApply.apply(this,args);apply();return result;};
function init(){apply();document.addEventListener('click',e=>{if(e.target.closest('#settings-save,[onclick="saveAstrologerSettings()"],[onclick="resetAstrologerSettings()"]'))setTimeout(()=>apply(),0);});window.addEventListener('kp-preferences-changed',()=>apply());}
window.KPDeveloperCredit=Object.freeze({name:NAME,mobile:MOBILE,text:CREDIT,apply});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,100));else init();})();
